CREATE TABLE tenants (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE users (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE memberships (tenant_id text REFERENCES tenants(id), user_id text REFERENCES users(id), role text NOT NULL CHECK(role IN ('owner','teacher','guardian')), active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,user_id));
CREATE TABLE auth_sessions (token_hash text PRIMARY KEY, user_id text NOT NULL, tenant_id text NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE students (tenant_id text NOT NULL REFERENCES tenants(id), id text NOT NULL, name text NOT NULL, phone text NOT NULL DEFAULT '', note text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id));
CREATE TABLE guardians (tenant_id text NOT NULL, student_id text NOT NULL, user_id text NOT NULL, PRIMARY KEY(tenant_id,student_id,user_id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE courses (tenant_id text NOT NULL REFERENCES tenants(id), id text NOT NULL, name text NOT NULL, duration integer NOT NULL CHECK(duration > 0), debit integer NOT NULL CHECK(debit > 0), color text NOT NULL DEFAULT '#49756b', PRIMARY KEY(tenant_id,id));
CREATE TABLE packages (tenant_id text NOT NULL, id text NOT NULL, course_id text NOT NULL, name text NOT NULL, purchased integer NOT NULL CHECK(purchased > 0), gift integer NOT NULL CHECK(gift >= 0), price integer NOT NULL CHECK(price >= 0), valid_days integer NOT NULL CHECK(valid_days > 0), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,course_id) REFERENCES courses(tenant_id,id));
CREATE TABLE grants (tenant_id text NOT NULL, id text NOT NULL, student_id text NOT NULL, course_id text NOT NULL, package_name text NOT NULL, purchased integer NOT NULL CHECK(purchased > 0), gift integer NOT NULL CHECK(gift >= 0), source text NOT NULL CHECK(source IN ('opening','receipt')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id), FOREIGN KEY(tenant_id,course_id) REFERENCES courses(tenant_id,id));
CREATE TABLE receipts (tenant_id text NOT NULL, id text NOT NULL, grant_id text NOT NULL, amount integer NOT NULL CHECK(amount >= 0), method text NOT NULL CHECK(method IN ('cash','external')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,grant_id), FOREIGN KEY(tenant_id,grant_id) REFERENCES grants(tenant_id,id));
CREATE TABLE lessons (tenant_id text NOT NULL, id text NOT NULL, course_id text NOT NULL, teacher_id text NOT NULL, room text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, capacity integer NOT NULL CHECK(capacity > 0), debit integer NOT NULL CHECK(debit > 0), version integer NOT NULL DEFAULT 1, PRIMARY KEY(tenant_id,id), CHECK(ends_at > starts_at), FOREIGN KEY(tenant_id,course_id) REFERENCES courses(tenant_id,id), FOREIGN KEY(tenant_id,teacher_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE bookings (tenant_id text NOT NULL, id text NOT NULL, session_id text NOT NULL, student_id text NOT NULL, state text NOT NULL CHECK(state IN ('confirmed','attended','absent','cancelled','leave')), makeup_id text, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,session_id,student_id), FOREIGN KEY(tenant_id,session_id) REFERENCES lessons(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE makeup_credits (tenant_id text NOT NULL, id text NOT NULL, student_id text NOT NULL, course_id text NOT NULL, origin_booking text NOT NULL, state text NOT NULL CHECK(state IN ('available','reserved','used')), expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,origin_booking), FOREIGN KEY(tenant_id,origin_booking) REFERENCES bookings(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id), FOREIGN KEY(tenant_id,course_id) REFERENCES courses(tenant_id,id));
ALTER TABLE bookings ADD FOREIGN KEY(tenant_id,makeup_id) REFERENCES makeup_credits(tenant_id,id);
CREATE UNIQUE INDEX makeup_one_reservation ON bookings(tenant_id,makeup_id) WHERE makeup_id IS NOT NULL AND state IN ('confirmed','attended','absent');
CREATE TABLE attendance (tenant_id text NOT NULL, booking_id text NOT NULL, revision integer NOT NULL CHECK(revision > 0), status text NOT NULL CHECK(status IN ('attended','absent','unmarked')), PRIMARY KEY(tenant_id,booking_id), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id));
CREATE TABLE attendance_history (tenant_id text NOT NULL, booking_id text NOT NULL, revision integer NOT NULL, status text NOT NULL, reason text NOT NULL, actor_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,booking_id,revision), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id));
CREATE TABLE ledger (tenant_id text NOT NULL, id text NOT NULL, grant_id text NOT NULL, student_id text NOT NULL, delta integer NOT NULL CHECK(delta <> 0), kind text NOT NULL CHECK(kind IN ('purchase','gift','opening','consume','reversal')), booking_id text, revision integer, reversal_of text, actor_id text NOT NULL REFERENCES users(id), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), seq bigint GENERATED ALWAYS AS IDENTITY, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,reversal_of), FOREIGN KEY(tenant_id,grant_id) REFERENCES grants(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id), FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id), FOREIGN KEY(tenant_id,reversal_of) REFERENCES ledger(tenant_id,id));
CREATE INDEX ledger_grant ON ledger(tenant_id,grant_id);
CREATE INDEX ledger_student ON ledger(tenant_id,student_id,seq);
CREATE TABLE commands (tenant_id text NOT NULL REFERENCES tenants(id), actor_id text NOT NULL REFERENCES users(id), key text NOT NULL, hash text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,actor_id,key));
CREATE TABLE audit_events (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), actor_id text NOT NULL REFERENCES users(id), action text NOT NULL, subject text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), event text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'not_configured', created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'ledger is append-only'; END $$;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
CREATE TRIGGER history_immutable BEFORE UPDATE OR DELETE ON attendance_history FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
